const input = $("Prepare Send Payload").first().json;
const templates = $input.all().map((i) => i.json);

// YCloud's "Get templates" returns every template on the account (no server-side filter
// configured on that node) — filter here by name + language.
const matches = templates.filter((t) => t.name === input.meta_template_name);
const template =
  matches.find((t) => t.language === input.meta_language) || matches[0];

if (!template) {
  return [
    {
      json: {
        __error: true,
        code: 404,
        message: `No WHATSAPP template found in YCloud for
  meta_template_name="${input.meta_template_name}" and meta_language="${input.meta_language}"`,
      },
    },
  ];
}

// NOTE: unverified — confirm the exact status field/enum YCloud returns for a template
// (assumed to mirror Meta's Cloud API: APPROVED / PENDING / REJECTED).
const status = template.status || template.meta_status;
if (status !== "APPROVED") {
  return [
    {
      json: {
        __error: true,
        code: 409,
        message: `Template "${input.meta_template_name}" is not approved yet
  (status: ${status || "PENDING"})`,
      },
    },
  ];
}

if (!template.wabaId) {
  return [
    {
      json: {
        __error: true,
        code: 500,
        message: `Template "${input.meta_template_name}" has no wabaId on the
  YCloud response`,
      },
    },
  ];
}

// Drift check: the set of {{named}} placeholders in the live BODY component must match
// exactly the keys we resolved via variables_schema. Catches a template edited on Meta's
// side without updating the CommunicationTemplate row.
//
// IMPORTANT: WhatsApp's template API is order-sensitive for the parameters array even
// when each parameter carries a parameter_name — so besides validating the *set* of
// names, we capture placeholderOrder (first-occurrence order in the body text) and pass
// it downstream so the send step can emit parameters in the exact order Meta expects,
// regardless of the (unordered, possibly jsonb-reshuffled) key order of variables_schema.
const bodyComponent = Array.isArray(template.components)
  ? template.components.find((c) => String(c.type).toUpperCase() === "BODY")
  : null;
const placeholderOrder = [];
const seenPlaceholders = new Set();
if (bodyComponent && typeof bodyComponent.text === "string") {
  const found = bodyComponent.text.match(/\{\{\s*([^{}]+?)\s*\}\}/g) || [];
  found.forEach((m) => {
    const name = m.replace(/[{}]/g, "").trim();
    if (!seenPlaceholders.has(name)) {
      seenPlaceholders.add(name);
      placeholderOrder.push(name);
    }
  });
}
const placeholderNames = new Set(placeholderOrder);
const providedNames = new Set(Object.keys(input.variables || {}));
const missing = [...placeholderNames].filter((n) => !providedNames.has(n));
const extra = [...providedNames].filter((n) => !placeholderNames.has(n));
if (missing.length || extra.length) {
  return [
    {
      json: {
        __error: true,
        code: 400,
        message: `Variable mismatch for template "${input.meta_template_name}":
  missing=[${missing.join(", ")}] extra=[${extra.join(", ")}]. The template on Meta changed — update variables_schema on
  this CommunicationTemplate.`,
      },
    },
  ];
}

return [
  {
    json: {
      ...input,
      template_code: template.name,
      wabaId: template.wabaId,
      template_variable_order: placeholderOrder,
    },
  },
];

const input = $('Validate Template & Params').first().json;
const res = $input.first().json;

// The custom YCloud node either returns the successful API response directly,
// or (via onError: continueErrorOutput) an error-shaped item. Exact field names
// are unverified — confirm with a live test send and adjust if needed.
const errorMessage = res.error?.message || (typeof res.error === 'string' ? res.error : null) || res.message;
const looksLikeSuccess = res.id != null || res.status != null || res.messages?.[0]?.id != null;

if (looksLikeSuccess && !errorMessage) {
  const messageId = res.id || res.messages?.[0]?.id || null;
  const status = res.status || res.messages?.[0]?.status || 'sent';
  return [{ json: {
    ...input,
    success: true,
    message_id: messageId,
    ycloud_status: status
  } }];
}

return [{ json: { __error: true, code: 502, message: `YCloud rejected the message: ${errorMessage || JSON.stringify(res)}` } }];

const input = $input.first().json;
const body = input.body ?? input;

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const patientId = String(body.id ?? '').trim();
if (!UUID_PATTERN.test(patientId)) throw new Error('id must be a valid patient UUID');

// template_code is now a free code — validated against communication_templates
// (see "Get Communication Template" / "Template Found?") instead of a hardcoded enum.
const templateCode = String(body.template_code ?? '').trim();
if (!templateCode) throw new Error('template_code is required');

// Backwards compatibility: the patient-profile dialog still sends "appointment_id"
// directly. Newer callers (e.g. alerts) send the generic reference_table/reference_id pair.
let referenceTable = String(body.reference_table ?? '').trim();
let referenceId = String(body.reference_id ?? '').trim();
if (!referenceTable && !referenceId && body.appointment_id) {
  referenceTable = 'appointments';
  referenceId = String(body.appointment_id).trim();
}

const alertInstanceId = body.alert_instance_id != null && body.alert_instance_id !== ''
  ? String(body.alert_instance_id).trim()
  : '';
const performedBy = body.performed_by != null && body.performed_by !== ''
  ? String(body.performed_by).trim()
  : '';
if (alertInstanceId && !performedBy) throw new Error('performed_by is required when alert_instance_id is provided');

return [{
  json: {
    patient_id: patientId,
    template_code: templateCode,
    reference_table: referenceTable,
    reference_id: referenceId,
    alert_instance_id: alertInstanceId,
    performed_by: performedBy
  }
}];

