const phone = '+' + String(patient.phone_number || '').replace(/\D/g, '');

const pending = (Number(inv.total) - Number(inv.paid_amount || 0)).toFixed(2);
const amountFormatted = `${inv.currency || ''} ${pending}`.trim();
