const input = $input.first().json;
const body = input.body || {};
const name = String(body.name || '').trim();
const phone = String(body.phone_number || '').trim();
const emailRaw = String(body.email || '').trim();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const missing = [];
if (!name) missing.push('name');
if (!phone) missing.push('phone_number');

if (missing.length > 0) {
  return [{ json: { __error: true, code: 400, message: `Missing required fields: ${missing.join(', ')}` } }];
}

if (emailRaw && !emailRegex.test(emailRaw)) {
  return [{ json: { __error: true, code: 400, message: 'Invalid email format' } }];
}

return [{ json: { name, phone_number: phone, email: emailRaw } }];

